            'only_upper' => 'Bao gồm cả người dùng thuộc tổ chức cấp trên của tổ chức được chia sẻ dữ liệu',
            'only_downer' => 'Bao gồm cả người dùng thuộc tổ chức cấp dưới của tổ chức được chia sẻ dữ liệu',
