        'help' => [
            'site_name' => 'Tên trang hiển thị ở góc trên bên trái của trang.',
            'site_name_short' => 'Tên rút gọn của trang, hiển thị khi menu được thu gọn.',
            'site_logo' => 'Logo của trang. Kích thước khuyến nghị: 200px * 40px',
            'site_logo_mini' => 'Logo của trang (biểu tượng nhỏ). Kích thước khuyến nghị: 40px * 40px',
            'site_favicon' => 'Favicon của trang (.ico), dùng cho dấu trang trình duyệt v.v. Kích thước khuyến nghị: 16px * 16px',
            'site_skin' => 'Chọn màu chủ đề của trang. *Sau khi lưu, thay đổi sẽ được áp dụng khi tải lại trang.',
            'site_layout' => 'Chọn bố cục menu của trang ở bên trái. *Sau khi lưu, thay đổi sẽ được áp dụng khi tải lại trang.',
            'ui_design' => 'Chọn thiết kế cho trang đăng nhập và các trang quản trị. "Hiện đại" là thiết kế mới với tông trắng và xám, "Cổ điển" là thiết kế đã dùng từ trước đến nay. Mặc định là "Hiện đại". Nếu muốn quay lại thiết kế cũ, vui lòng chọn "Cổ điển". *Sau khi lưu, thay đổi sẽ được áp dụng khi tải lại trang.<br/>Nếu thiết kế đã được thiết lập trên máy chủ (EXMENT_UI_DESIGN trong .env), giá trị đó sẽ được ưu tiên và không thể thay đổi tại đây.',
            'filter_search_type' => 'Thiết lập phương thức tìm kiếm dữ liệu đã đăng ký. *Với khớp một phần, hiệu năng có thể bị ảnh hưởng tùy theo số lượng dữ liệu.',
            'grid_filter_disable_flg' => 'Các mục được đánh dấu sẽ bị ẩn trong các mục lọc của trang danh sách dữ liệu.',
            'system_values_pos' => 'Thiết lập vị trí hiển thị các mục hệ thống trên màn hình chỉnh sửa và màn hình chi tiết dữ liệu.',
            'data_submit_redirect' => 'Có thể thiết lập trang chuyển đến mặc định sau khi lưu dữ liệu tùy chỉnh. Khi thiết lập mục này, hộp kiểm trang chuyển đến sau khi lưu sẽ được đánh dấu sẵn trên trang nhập dữ liệu.',
            'header_user_info' => 'Có thể thiết lập nội dung hiển thị trong thông tin người dùng ở đầu trang. Nếu để trống, nội dung sẽ bị ẩn.',
            'allowed_locales' => 'Các ngôn ngữ người dùng có thể chọn ở menu góc trên bên phải, trang đăng nhập và cài đặt của họ. Để trống thì là tất cả các ngôn ngữ đã cài. Luôn có thể chọn ngôn ngữ của site.',
            'locale_from_browser' => 'Khi CÓ, người dùng chưa chọn ngôn ngữ sẽ thấy các trang bằng ngôn ngữ của trình duyệt (trong số các ngôn ngữ có thể chọn). Khi KHÔNG, bằng ngôn ngữ của site.',
            'grid_inline_edit_available' => 'Khi CÓ, có thể thay đổi giá trị ngay trong danh sách dữ liệu bằng cách nhấp đúp vào ô hoặc nhấp vào biểu tượng bút chì. Khi KHÔNG, không dùng chỉnh sửa trực tiếp trong bất kỳ danh sách dữ liệu nào. Chỉnh sửa hàng loạt và trang chỉnh sửa dữ liệu vẫn dùng được như trước.',
            'api_available' => 'Vui lòng tạo khóa Laravel trước khi chọn YES. Cách tạo vui lòng xem <a href="%suse-api" target="_blank">tại đây<i class="fa fa-external-link"></i></a>. Khi chọn YES, có thể sử dụng API.',
            'outside_api' => 'Khi chọn YES, hệ thống có thể thực hiện các xử lý giao tiếp với máy chủ bên ngoài, chẳng hạn như thông báo phiên bản mới nhất của Exment. Hệ thống chỉ nhận dữ liệu. *Nếu không thực hiện giao tiếp, ví dụ khi sử dụng trong môi trường không thể kết nối mạng bên ngoài, vui lòng chọn NO.',
            'grid_pager_count' => 'Số dòng hiển thị mặc định trên trang danh sách. Áp dụng cho toàn hệ thống.',
            'datalist_pager_count' => 'Số dòng hiển thị mặc định của dữ liệu trong tìm kiếm từ khóa và danh sách dữ liệu trên bảng điều khiển. Áp dụng cho toàn hệ thống.',
            'meili_host' => 'Ví dụ: http://127.0.0.1:7700',
            'meili_key' => 'Khóa API chính của máy chủ Meilisearch. Được lưu ở dạng mã hóa. Nếu xóa trống trường này, khóa rỗng sẽ được lưu và giá trị MEILISEARCH_KEY trong .env sẽ được sử dụng thay thế.',
            'meili_index' => 'Tên chỉ mục tổng hợp, ví dụ exment_global. Sau khi thay đổi, vui lòng chạy `php artisan exment:meili-index` để xây dựng lại.',
            'meili_global_search' => 'Tắt: quay lại tìm kiếm MySQL mặc định của Exment.',
            'meili_realtime_sync' => 'Bật: thay đổi bản ghi sẽ tự động đồng bộ sang Meilisearch (qua hàng đợi). Worker hàng đợi đọc cài đặt khi khởi động, vì vậy vui lòng khởi động lại worker sau khi thay đổi cài đặt Meilisearch.',
            'meili_batch_size' => 'Số tài liệu gửi mỗi lô khi lập chỉ mục (ví dụ 1000).',
            'meili_repair_enabled' => 'Bật: sửa chênh lệch giữa cơ sở dữ liệu và chỉ mục hằng ngày (cần trình lập lịch).',
            'meili_repair_at' => 'Thời điểm chạy sửa chữa (định dạng 24 giờ HH:MM, ví dụ 03:00).',
            'meili_filter_mode' => '"Tự động + Tùy chỉnh" = tự động chọn theo loại cột, đồng thời thêm/loại trừ trên màn hình cài đặt. "Chỉ tùy chỉnh" = chỉ dùng các cột đã cấu hình trên màn hình. Cần lập chỉ mục lại sau khi thay đổi.',
            'meili_dictionary' => 'Điều chỉnh độ chính xác tìm kiếm bằng từ đồng nghĩa và từ dừng. Chỉ thay đổi cài đặt chỉ mục nên không cần lập chỉ mục lại sau khi lưu (áp dụng trong vài giây).',
            'meili_dictionary_type' => '"Từ đồng nghĩa" = nhóm các từ được coi là tương đương. "Từ dừng" = các từ bị bỏ qua khi tìm kiếm (trợ từ v.v.).',
            'meili_dictionary_word' => 'Từ đồng nghĩa = từ đại diện của nhóm. Từ dừng = từ cần bỏ qua (nhiều từ phân cách bằng dấu phẩy/xuống dòng).',
            'meili_dictionary_synonyms' => 'Các từ được coi là tương đương với từ đại diện, phân cách bằng dấu phẩy/xuống dòng (ví dụ: contract, agreement). Các từ sẽ là đồng nghĩa của nhau.',
            'meili_filter_alias' => 'Các cột có cùng ý nghĩa (ví dụ status, contract_status) dùng chung một bí danh sẽ được gộp thành một nhóm bộ lọc. Chỉ áp dụng cho bộ lọc khớp chính xác; khi thay đổi bí danh, chỉ mục sẽ tự động được lập lại khi lưu.',
            'meili_filter_include_mode' => 'Thêm: thêm cột vào bộ lọc. Loại trừ: bỏ cột được chọn tự động khỏi bộ lọc (chỉ có hiệu lực ở chế độ "Tự động + Tùy chỉnh").',
            'permission_available' => 'Khi chọn YES, các mục có thể truy cập sẽ được quản lý theo người dùng và vai trò.',
            'organization_available' => 'Khi chọn YES, có thể tạo tổ chức, phòng ban mà người dùng trực thuộc.',
            'logging_toggle_available' => 'Khi chọn YES, các thao tác màn hình chậm sẽ được ghi vào "Nhật ký hiệu năng hệ thống" (menu "Cài đặt: Hệ thống"): URL của màn hình (các giá trị tìm kiếm v.v. được ẩn), người dùng, thời gian xử lý và SQL (giữ "?", không có giá trị).',
            'logging_slow_request_seconds' => 'Ghi nhật ký khi màn hình xử lý mất từ số giây này trở lên. 0: không ghi theo điều kiện này. Khi giá trị này và "số giây của SQL chậm" đều là 0, mọi thao tác sẽ được ghi lại (chỉ dùng khi điều tra).',
            'logging_slow_sql_seconds' => 'Ghi nhật ký khi một câu SQL mất từ số giây này trở lên. 0: không ghi theo điều kiện này.',
            'logging_max_per_hour' => 'Số bản ghi nhật ký tối đa được lưu trong một giờ. Phần vượt quá sẽ không được ghi. 0: không giới hạn.',
            'system_admin_users' => 'Vui lòng thiết lập người dùng sẽ là quản trị viên hệ thống.',
            'system_mail' => 'Thiết lập cài đặt khi gửi email từ hệ thống.',
            'system_mail_from' => 'Địa chỉ email gửi đi. Email sẽ được gửi với địa chỉ này làm người gửi (From).',
            'system_mail_from_view_name' => 'Vui lòng nhập tên hiển thị của người gửi. Tên này sẽ hiển thị cho người nhận. *Nếu đã nhập tên hiển thị người gửi trong mẫu thông báo, cài đặt đó sẽ được ưu tiên. Có thể nhập tham số.',
            'system_mail_encryption' => 'Vui lòng nhập giao thức mã hóa email bằng chữ thường. (ssl, tls v.v.)',
            'system_mail_body_type' => 'Vui lòng chọn loại nội dung của email sẽ gửi.',
            'test_mail' => 'Gửi email thử đến địa chỉ đã nhập. <br /> <b>*Vui lòng lưu cài đặt email ở trên trước khi thực hiện. Cài đặt đang nhập dở sẽ không có hiệu lực.</b>',
            'system_slack_user_column' => 'Vui lòng chọn cột tùy chỉnh trong bảng người dùng để thiết lập Slack ID. Khi gửi thông báo Slack, có thể thêm lượt nhắc (mention) đến ID người dùng đó.',
            'system_line_oa_basic_id' => 'Basic ID của tài khoản LINE Official Account (bắt đầu bằng @). Được dùng để tạo deep link liên kết tài khoản.',
            'safety_check_auto_enabled' => 'Khi chọn YES, thông báo sẽ được gửi tự động khi phát hiện động đất có cường độ từ "Cường độ địa chấn tối thiểu để tự động gửi" trở lên.',
            'safety_check_min_scale' => 'Thông báo sẽ được gửi tự động khi phát hiện động đất có cường độ (cường độ lớn nhất toàn quốc) từ mức đã chọn trở lên.',
            'safety_check_cooldown_minutes' => 'Khoảng thời gian trước khi gửi lại cho cùng một trận động đất.<br/>Ví dụ: nếu nhận được các bản tin của cùng một trận động đất trong khoảng 02:02 đến 02:12, cài đặt 60 phút sẽ chỉ gửi một lần lúc 02:02, còn cài đặt 5 phút sẽ gửi hai lần lúc 02:02 và 02:12.<br/>Với trận động đất khác, thông báo sẽ được gửi bất kể khoảng thời gian này.',
            'safety_check_comment_window_minutes' => 'Thời gian (phút) nhận phản hồi bổ sung sau khi người dùng nhấn nút trả lời xác nhận an toàn.',
            'safety_check_max_bulletin_age_minutes' => 'Vui lòng giữ giá trị 10. Thông thường không cần thay đổi cài đặt này.',
            'safety_check_resend_throttle_minutes' => 'Thiết lập khoảng thời gian phải chờ trước khi có thể gửi lại thông báo. Không thể gửi lại trong khoảng thời gian này. Nhập 0 để không giới hạn.',
            'safety_check_answer_url_expire_days' => 'Số ngày có thể sử dụng liên kết trả lời trong email kể từ khi gửi. Liên kết của đợt xác nhận an toàn đã kết thúc sẽ không dùng được dù còn hạn. Người chưa trả lời có liên kết đã hết hạn sẽ nhận liên kết mới khi gửi lại. Nhập 0 để không giới hạn thời hạn.',
            'safety_check_target_organizations' => 'Chỉ gửi cho người dùng thuộc các tổ chức đã chọn (bao gồm tổ chức con). Để trống thì gửi cho tất cả người dùng.',
            'safety_check_target_view' => 'Khi chọn một chế độ xem của bảng người dùng, chỉ gửi cho người dùng khớp điều kiện của chế độ xem đó. Để trống thì không lọc.',
            'safety_check_excluded_users' => 'Không gửi cho những người dùng đã chọn (ví dụ: người đã nghỉ việc, người bên ngoài).',
            'template' => 'Khi chọn mẫu, các bảng, cột và biểu mẫu sẽ được cài đặt tự động.',
            'role_one_user_organization' => 'Vui lòng đăng ký ít nhất một người dùng hoặc tổ chức cho quyền.',
            'userdashboard_available' => 'Khi chọn YES, chức năng bảng điều khiển người dùng sẽ được sử dụng, cho phép người dùng đăng nhập tự tạo bảng điều khiển riêng.',
            'userview_available' => 'Khi chọn YES, chức năng chế độ xem người dùng sẽ được sử dụng, cho phép người dùng đăng nhập tự tạo chế độ xem riêng.',
            'default_date_format' => 'Thiết lập định dạng hiển thị ngày và giờ.',
            'password_policy' => 'Thiết lập chính sách mật khẩu đăng nhập.',
            'complex_password' => 'Khi chọn YES, mật khẩu phải dài ít nhất 12 ký tự và chứa ba loại ký tự (chữ hoa, chữ thường, số, ký hiệu).',
            'password_expiration_days' => 'Thiết lập số ngày hiệu lực của mật khẩu. Nếu nhập 0, mật khẩu sẽ không hết hạn.',
