            'start_status_name' => 'Vui lòng thiết lập tên trạng thái khi bắt đầu quy trình làm việc.',
            'datalock_flg' => 'Thiết lập có không cho chỉnh sửa dữ liệu đích khi quy trình làm việc ở trạng thái này hay không. Chọn YES nếu không muốn cho chỉnh sửa.',
            'workflow_type' => 'Chọn loại quy trình làm việc.<br />"Dùng chung" có thể sử dụng cho nhiều bảng, nhưng không thể dùng cột tùy chỉnh để thiết lập điều kiện hành động hoặc chọn người xử lý.<br />"Chỉ dùng cho bảng" yêu cầu chọn trước một bảng, nhưng có thể dùng cột tùy chỉnh để thiết lập điều kiện hành động và chọn người xử lý.',
            'workflow_edit_flg' => 'Nếu chọn YES, quyền chỉnh sửa sẽ được cấp cho người xử lý tiếp theo khi thực thi hành động. (Nếu chọn NO, quyền xem sẽ được cấp.)',
            'work_conditions' => 'Thiết lập trạng thái sau khi thực thi hành động. Nhấp nút "Thay đổi" để thay đổi thiết lập. Nội dung thiết lập khác nhau tùy theo loại quy trình làm việc.',
            'work_targets' => 'Chọn người dùng, tổ chức... có thể thực thi hành động này. Nhấp nút "Thay đổi" để thay đổi thiết lập.',
            'work_targets2' => 'Chọn loại người dùng có thể thực thi hành động này.<br />[Do người thực thi hành động trước chọn] Người đã thực thi hành động trước sẽ chọn người thực thi hành động này.<br/>[Thiết lập trước] Chỉ người dùng hoặc tổ chức cụ thể mới có thể thực thi.<br/>[Lấy từ thông tin người thực thi] Chỉ người dùng hoặc tổ chức được thiết lập trong cột tùy chỉnh của người thực thi mới có thể thực thi.',
            'work_conditions_common' => 'Thiết lập trạng thái sau khi thực thi hành động này.',
            'work_conditions_table' => 'Thiết lập điều kiện để thực thi hành động này và trạng thái sau khi thực thi. Có thể thiết lập tối đa 3 điều kiện.<br />*Nếu luôn thực thi một hành động cố định, chỉ cần thiết lập [Trạng thái sau khi thực thi] của [Điều kiện 1].',
            'flow_next_type' => 'Thiết lập số người cần thực thi hành động này để chuyển sang trạng thái tiếp theo.',
            'beginning' => 'Chọn tối đa một quy trình làm việc sử dụng cho mỗi bảng.<br />*Ngay cả khi thay đổi quy trình làm việc sử dụng, các quy trình đang tiến hành vẫn được thực thi theo quy trình làm việc trước khi thay đổi.',
            'status_from' => 'Thiết lập trạng thái cần có để thực thi hành động đó.',
            'status_to' => 'Thiết lập trạng thái sau khi thực thi hành động. *Vui lòng chọn trạng thái khác với trạng thái trước khi thực thi.',
            'setting_complete' => 'Hoàn tất cài đặt cho quy trình làm việc này.<br />Sau khi hoàn tất cài đặt, không thể thực hiện các thao tác sau.<br />• Thêm, xóa, thay đổi thứ tự trạng thái',
            'deactivate_complete' => '<span class="red bold">Xóa quy trình làm việc này.</span>Khi xóa, vui lòng lưu ý các điểm sau.<br />• Không thể khôi phục quy trình làm việc.<br />• Các quy trình làm việc đang tiến hành sẽ bị vô hiệu hóa.<br />• Ngay cả khi thiết lập "Không cho chỉnh sửa dữ liệu" trong cài đặt trạng thái là YES, dữ liệu đang bị khóa chỉnh sửa sẽ có thể chỉnh sửa lại.<br /><br />Chỉ thực hiện khi bạn thực sự muốn xóa.',
            'ignore_work' => 'Khi chọn mục này, "người dùng có thể thực thi" được thiết lập cho hành động này sẽ không được tính là người xử lý.<br />Vui lòng chọn khi hành động quay lại trạng thái trước như "Từ chối", "Trả lại", hoặc khi quản trị viên phê duyệt theo trường hợp đặc biệt.',
            'flow_executed_user_count' => 'Trạng thái sẽ không thay đổi cho đến khi đủ số người cần thiết thực thi hành động.',
            'add_notify_flg' => 'Thêm thiết lập thông báo trong hệ thống cho "người xử lý tiếp theo" khi thực thi quy trình làm việc. Chọn YES để thêm.<br/>*Chỉ có thể thiết lập tại màn hình này khi hoàn tất cài đặt quy trình làm việc. Khi cập nhật, vui lòng thiết lập từ màn hình "Thông báo".',
            'target_column' => 'Các cột có loại cột tùy chỉnh là "Người dùng" và "Tổ chức" sẽ được hiển thị trong danh sách lựa chọn.',
            'target_column_get_by_userinfo' => 'Trong các cột có loại cột tùy chỉnh là "Người dùng" và "Tổ chức" được thiết lập trong bảng "Người dùng", các cột được thiết lập chỉ mục tìm kiếm sẽ được hiển thị trong danh sách lựa chọn.',
            'target_user_org' => 'Chỉ :type có quyền truy cập bảng ":table_view_name" mới được hiển thị trong danh sách lựa chọn. Nếu không thấy :type muốn thêm, vui lòng thêm quyền từ cài đặt nhóm vai trò.',
            'get_by_userinfo_base' => 'Khi người dùng có thể thực thi trong cài đặt hành động là "Lấy từ thông tin người thực thi", hãy chọn người dùng được dùng làm cơ sở để lấy người dùng / tổ chức thực thi hành động tiếp theo.<br />[Người thực thi đầu tiên] Dựa trên người đã thực thi hành động đầu tiên của quy trình.<br />[Người thực thi] Dựa trên người đã thực thi hành động đó.<br />[Người tạo dữ liệu] Dựa trên người đã tạo dữ liệu đó.',
