            'column_type' => 'Vui lòng chọn loại của cột này. Khi nhập dữ liệu, biểu mẫu sẽ thay đổi theo loại cột.',
            'index_enabled' => 'Nếu chọn YES, chỉ mục tìm kiếm sẽ được thêm vào. Nhờ đó có thể lọc theo điều kiện khi tìm kiếm và trong chế độ xem.<br/>Chi tiết vui lòng xem <a href="%s" target="_blank">tại đây<i class="fa fa-external-link"></i></a>',
