            'min_max_width' => 'Nhập giá trị nhỏ nhất và lớn nhất của độ rộng cột khi hiển thị danh sách, dưới dạng số nguyên (px).',
            'text_align' => 'Vui lòng chọn cách căn chỉnh khi hiển thị danh sách.',
            'grid_preset' => 'Chọn từ thư viện cài đặt sẵn cách hiển thị cột này trong danh sách dữ liệu.<br/>Nếu muốn thay đổi giao diện, đừng điều chỉnh riêng cột này mà hãy tạo cài đặt sẵn mới bằng nút bút chì, để các cột khác cũng có thể chọn cùng giao diện.',
            'grid_style' => 'Chọn cách hiển thị giá trị của cột này trong danh sách dữ liệu. Nếu chọn "Mặc định", cách hiển thị sẽ giữ nguyên như trước.',
            'grid_color' => 'Màu chữ của giá trị. Với cột lựa chọn chưa đặt "Màu theo giá trị", màu sẽ được gán tự động theo thứ tự các lựa chọn.',
            'grid_bg_color' => 'Màu nền của thẻ, nhãn bo tròn hoặc toàn bộ ô. Nếu để trống, màu sẽ được tạo tự động từ màu chữ.',
            'grid_border_color' => 'Màu viền của thẻ, nhãn bo tròn hoặc toàn bộ ô. Nếu để trống, màu sẽ được tạo tự động từ màu chữ.',
            'grid_font_weight' => 'Độ đậm của chữ trong giá trị.',
            'grid_icon' => 'Biểu tượng hiển thị trước giá trị, chọn bằng nút bên cạnh trường.<br/>Biểu tượng không hiển thị với kiểu ảnh đại diện, thanh tiến độ và tô màu toàn ô.',
            'grid_nowrap' => 'Nếu chọn YES, chữ trong ô sẽ không bị xuống dòng.',
            'grid_value_colors' => 'Chọn màu hiển thị trong danh sách cho từng lựa chọn. Giá trị chưa được chọn màu sẽ được gán màu tự động theo thứ tự các lựa chọn.<br/>Với thanh tiến độ, mỗi dòng là một ngưỡng: màu được áp dụng khi giá trị lớn hơn hoặc bằng ngưỡng đó.',
            'number_format' => 'Nếu chọn YES, trường văn bản sẽ hiển thị số có dấu phân cách hàng nghìn.',
            'force_caculate' => 'Nếu chọn YES, phép tính sẽ được thực hiện ngay cả khi không có giá trị.',
