            'updown_button' => 'Nếu chọn YES, các nút "+" và "-" sẽ hiển thị trên biểu mẫu.',
            'select_item' => 'Vui lòng nhập các lựa chọn, mỗi lựa chọn một dòng.',
            'datetime_now_saving' => 'Khi tạo mới hoặc cập nhật dữ liệu, giá trị sẽ được tự động đăng ký theo ngày giờ thực hiện. * Người dùng không thể tự đặt giá trị.',
            'datetime_now_creating' => 'Khi tạo mới dữ liệu, giá trị sẽ được tự động đăng ký theo ngày giờ thực hiện. * Người dùng không thể tự đặt giá trị.',
            'select_item_valtext' => 'Nhập các lựa chọn, mỗi lựa chọn một dòng. Phần trước dấu phẩy là giá trị, phần sau dấu phẩy là nhãn.<br/>Ví dụ:「1,Người lớn<br/>2,Vị thành niên」→ "1" là giá trị được lưu vào dữ liệu, "Người lớn" là nhãn mà người dùng chọn.',
            'select_target_table' => 'Vui lòng chọn bảng làm đối tượng lựa chọn.',
            'select_load_ajax' => 'Nếu chọn YES, ban đầu các lựa chọn sẽ không được tải mà dữ liệu sẽ được tìm kiếm theo giá trị người dùng nhập để thu hẹp danh sách gợi ý.<br/> * Bất kể cài đặt này, nếu số lượng dữ liệu từ %s trở lên, chế độ thu hẹp sẽ được áp dụng để cải thiện hiệu năng.',
            'assign_me_enabled' => 'Nếu chọn YES, một nút sẽ hiển thị bên cạnh cột này. Khi nhấn, người dùng đang đăng nhập sẽ được chọn.',
            'quickadd_enabled' => 'Nếu chọn YES, nút "Thêm mới" sẽ hiển thị bên cạnh các lựa chọn. Chỉ cần nhập tên là có thể tạo bản ghi ngay trong bảng được tham chiếu. Nút sẽ bị ẩn nếu người dùng không có quyền tạo trong bảng đó.',
            'paste_attach_enabled' => 'Nếu chọn YES, hình ảnh dán bằng Ctrl+V trên màn hình sẽ được thêm vào tệp đính kèm của cột này. Khi dán bên trong trình soạn thảo văn bản định dạng, hình ảnh vẫn được chèn vào nội dung như trước.',
            'showing_all_user_organizations' => 'Nếu chọn YES, tất cả người dùng/tổ chức sẽ hiển thị trong danh sách lựa chọn mà không kiểm tra quyền truy cập bảng. *Nếu cài đặt này là NO, danh sách lựa chọn chỉ gồm những người dùng và tổ chức có thể truy cập bảng này.',
            'select_target_view' => 'Chỉ định chế độ xem điều kiện khi muốn lọc dữ liệu. Vui lòng tạo trước chế độ xem điều kiện trên trang cài đặt bảng tùy chỉnh.',
            'select_import_column_id' => 'Khi nhập dữ liệu, có thể chỉ định cột tùy chỉnh dùng để xác định dữ liệu của bảng được chọn. Nếu không đặt, id sẽ được sử dụng. Chi tiết vui lòng xem&nbsp;<a href="%s" target="_blank">tại đây<i class="fa fa-external-link"></i></a>&nbsp;.',
            'select_import_column_id_key' => 'Thay đổi cách chỉ định dữ liệu của bảng cha',
            'select_export_column_id' => 'Khi xuất dữ liệu, có thể chỉ định cột tùy chỉnh dùng để xuất dữ liệu của bảng được chọn. Nếu không đặt, id sẽ được xuất.',
            'true_value' => 'Vui lòng nhập giá trị được đăng ký khi lưu lựa chọn thứ nhất.',
