            'suggest_input' => 'Nếu chọn YES, có thể hiển thị danh sách gợi ý nhập từ dữ liệu đã đăng ký.<br/> * Để sử dụng, vui lòng đặt "Chỉ mục tìm kiếm" thành YES.',
            'regex_validate' => '(Dành cho người dùng nâng cao) Đặt nội dung được phép nhập bằng biểu thức chính quy. Nếu đặt giá trị cho mục này, cài đặt "Ký tự được phép" ở trên sẽ bị vô hiệu. Chi tiết vui lòng xem&nbsp;<a href="%s" target="_blank">tại đây<i class="fa fa-external-link"></i></a>&nbsp;.',
            'auto_number_format' => 'Đặt quy tắc đánh số khi đăng ký. Chi tiết về quy tắc vui lòng xem <a href="%s" target="_blank">tại đây<i class="fa fa-external-link"></i></a>.',
            'calc_formula' => 'Có thể đặt công thức tính toán sử dụng các trường khác. Khi nhập các mục trên màn hình nhập dữ liệu, giá trị sẽ được tính tự động theo công thức đã đặt.',
