            'add_custom_view_flg' => 'Sau khi tạo cột tùy chỉnh, có thể thêm cột vào chế độ xem mặc định. Để thêm, vui lòng chọn YES.<br />*Chỉ có thể đặt khi tạo cột mới. Khi cập nhật, vui lòng đặt từ trang "Chế độ xem".',
            'add_table_label_flg' => 'Sau khi tạo cột tùy chỉnh, có thể thêm cột vào cột tiêu đề dùng cho gợi ý tìm kiếm và hiển thị tham chiếu từ bảng khác. Để thêm, vui lòng chọn YES.<br />*Chỉ có thể đặt khi tạo cột mới. Khi cập nhật, vui lòng đặt từ trang "Cài đặt mở rộng" của bảng.',
