            'check_radio_enabled' => 'Nếu chọn YES, mục sẽ hiển thị dạng nút radio hoặc hộp kiểm. (Nếu cho phép chọn nhiều, mục sẽ hiển thị dạng hộp kiểm; thông thường hiển thị dạng nút radio)',
