        ],
        'description_custom_view_columns' => 'Cài đặt các cột hiển thị trong chế độ xem.',
        'description_custom_view_kanban_columns' => 'Cài đặt các cột hiển thị trên thẻ. "Vị trí hiển thị" quyết định cột xuất hiện ở đâu trong thẻ, "Kiểu hiển thị" chọn mẫu hiển thị ô (thẻ, viên thuốc, huy hiệu...) - cùng thư viện với danh sách dữ liệu, nên chỉ cần định nghĩa giao diện một lần là dùng được trên cả hai màn hình.<br/>*Nếu để trống, thẻ sẽ theo cài đặt của cột; nếu cột cũng không có cài đặt thì hiển thị "tên mục + giá trị".<br/>*"Biểu tượng" nhập tên lớp Font Awesome (ví dụ fa-phone). Liệt kê các cặp "giá trị: lớp" phân cách bằng dấu phẩy để đặt biểu tượng riêng cho từng giá trị.<br/>*Nếu không cài đặt, thẻ chỉ hiển thị tiêu đề.<br/>*Cột được chọn làm nhãn màu, hạn chót (bộ đếm SLA) hoặc huy hiệu sẽ được hiển thị ở vị trí tương ứng, nên không hiển thị lặp lại trong phần nội dung thẻ.',
        'description_custom_view_calendar_columns' => 'Chọn cột ngày để hiển thị trên lịch.<br/>* Nếu cột tùy chỉnh không xuất hiện trong "Cột đích", nghĩa là chưa cài đặt <a href="%s" target="_blank">chỉ mục tìm kiếm<i class="fa fa-external-link"></i></a>. Vui lòng kiểm tra nội dung tại liên kết và tiến hành cài đặt.',
        'description_custom_view_groups' => 'Cài đặt các cột làm khóa nhóm trong chế độ xem.<br />*Nếu cột tùy chỉnh không xuất hiện trong "Cột đích", nghĩa là chưa cài đặt <a href="%s" target="_blank">chỉ mục tìm kiếm<i class="fa fa-external-link"></i></a>. Vui lòng kiểm tra nội dung tại liên kết và tiến hành cài đặt.',
        'description_custom_view_summaries' => 'Cài đặt các cột tổng hợp hiển thị trong chế độ xem.<br/>*Đối tượng tổng hợp là các cột thuộc loại "ID", "Số nguyên", "Số thập phân", "Tiền tệ", "Ngày". Để đếm tổng số bản ghi, vui lòng đặt cột đích là "ID" và loại tổng hợp là "Số lượng".',
        'description_custom_view_sorts' => 'Cài đặt thứ tự hiển thị dữ liệu trong chế độ xem.<br />*Nếu đăng ký từ 2 điều kiện trở lên, hiệu năng có thể giảm với các bảng có lượng dữ liệu rất lớn. Nếu cột tùy chỉnh không xuất hiện trong "Cột đích", nghĩa là chưa cài đặt <a href="%s" target="_blank">chỉ mục tìm kiếm<i class="fa fa-external-link"></i></a>. Vui lòng kiểm tra nội dung tại liên kết và tiến hành cài đặt.',
        'description_custom_view_filters' => 'Cài đặt điều kiện hiển thị dữ liệu trong chế độ xem.<br/>* Ngoài cài đặt này, dữ liệu còn được lọc để chỉ hiển thị dữ liệu mà người dùng đăng nhập có quyền.<br />*Nếu cột tùy chỉnh không xuất hiện trong "Cột đích", nghĩa là chưa cài đặt <a href="%s" target="_blank">chỉ mục tìm kiếm<i class="fa fa-external-link"></i></a>. Vui lòng kiểm tra nội dung tại liên kết và tiến hành cài đặt.',
        'description_custom_view_grid_filters' => 'Chỉ định các cột hiển thị làm lựa chọn trong "Bộ lọc" ở phía trên chế độ xem.<br/>*Nếu muốn hiển thị các mục mặc định của hệ thống, vui lòng không thêm cột vào danh sách này.<br/>*Nếu cột tùy chỉnh không xuất hiện trong "Cột đích", nghĩa là chưa cài đặt <a href="%s" target="_blank">chỉ mục tìm kiếm<i class="fa fa-external-link"></i></a>. Vui lòng kiểm tra nội dung tại liên kết và tiến hành cài đặt.',
        'description_custom_view_summary_filters' => '<br/>*"Bộ lọc" này dùng để thu hẹp dữ liệu trước khi tổng hợp, không phải kết quả đã tổng hợp.',
        'help' => [
            'custom_view_type' => 'Chế độ xem hệ thống: chế độ xem mà tất cả người dùng của bảng này đều có thể sử dụng. Chế độ xem người dùng: chế độ xem chỉ người tạo mới có thể sử dụng.',
            'grid_preset' => 'Hiển thị cột này trong danh sách dữ liệu theo mẫu hiển thị đã chọn.<br/>Được ưu tiên hơn cài đặt của cột.<br/>Dùng nút bút chì để tạo mới hoặc chỉnh sửa mẫu hiển thị.',
            'sort_type' => 'Chỉ định sắp xếp theo thứ tự tăng dần (nhỏ đến lớn) hay giảm dần (lớn đến nhỏ).',
            'sort_order_summaries' => 'Sắp xếp dữ liệu được lấy.<br />Sắp xếp theo thứ tự số tăng dần trong các "cột nhóm" và "cột tổng hợp".',
            'use_view_infobox' => 'Khi chọn YES, có thể đặt hộp thông tin ở phía trên chế độ xem để ghi nội dung công việc hoặc lời nhắn cho người dùng.',
            'view_infobox_title' => 'Vui lòng nhập tiêu đề hiển thị trong hộp thông tin.',
            'view_infobox' => 'Vui lòng nhập HTML hiển thị trong hộp thông tin. *Không thể nhập hình ảnh và script.',
            'order' => 'Thứ tự hiển thị các nút menu của chế độ xem tùy chỉnh.',
            'kanban_group_column' => 'Các lựa chọn của cột này sẽ trở thành các làn Kanban.<br/>*Chỉ có thể chọn cột lựa chọn đơn (không chọn nhiều). Nếu "Cách tạo các cột của bảng Kanban" là "Từ trạng thái của quy trình làm việc", cài đặt này không được sử dụng.',
            'kanban_swimlane_column' => 'Chia bảng Kanban theo chiều ngang theo giá trị của cột này.<br/>*Nếu không đặt, bảng sẽ hiển thị không chia.',
            'kanban_editable' => 'Nếu chọn YES, khi kéo thẻ sang làn khác, giá trị của "Cột dùng làm làn Kanban" sẽ được cập nhật.<br/>*Người dùng không có quyền chỉnh sửa dữ liệu thì không thể kéo dù đã chọn YES.',
            'inline_edit_enabled' => 'Nếu chọn NO, không dùng chỉnh sửa trực tiếp trong danh sách dữ liệu của chế độ xem này. Chỉnh sửa hàng loạt và trang chỉnh sửa dữ liệu vẫn dùng được như trước.<br/>*Nếu "Dùng chỉnh sửa trực tiếp trong danh sách dữ liệu" trong cài đặt hệ thống là NO, thì không thể chỉnh sửa trực tiếp dù đã chọn YES.',
            'kanban_max_count' => 'Số bản ghi tối đa hiển thị trên bảng Kanban. Số lượng lớn sẽ làm trang chậm hơn.',
            'gantt_start_column' => 'Cột ngày làm điểm bắt đầu của thanh.',
            'gantt_end_column' => 'Cột ngày làm điểm kết thúc của thanh.<br/>*Bản ghi đã qua ngày này mà tiến độ dưới 100 sẽ được hiển thị với viền đỏ "quá hạn".',
            'gantt_color_column' => 'Tô màu thanh theo giá trị của cột này.<br/>*Sử dụng nguyên màu đã đặt trong cài đặt màu giá trị của cột.',
            'gantt_progress_column' => 'Tiến độ (%) được hiển thị chồng bằng màu đậm hơn bên trong thanh.',
            'gantt_group_column' => 'Nhóm các hàng theo giá trị của cột này.<br/>*Với cột select_table (bảng mốc quan trọng...), cột ngày của bảng tham chiếu có tên cột hoặc tên hiển thị chứa "hạn", "due", "deadline", "期限"... sẽ được hiển thị làm hạn bằng dấu hình thoi. Nếu không có cột nào như vậy, cột ngày cuối cùng sẽ được sử dụng.',
            'gantt_parent_column' => 'Chọn cột tham chiếu đến chính bảng này, các bản ghi con sẽ được thụt lề dưới bản ghi cha.',
            'gantt_assignee_column' => 'Chọn cột người dùng để hiển thị ảnh đại diện trên mỗi hàng.',
            'gantt_max_count' => 'Số bản ghi tối đa hiển thị trên biểu đồ (10-2000, mặc định 500).',
            'kanban_source' => 'Nguồn tạo các làn Kanban.<br/>*Từ cột lựa chọn: các lựa chọn của cột sẽ trở thành các làn.<br/>*Từ quy trình làm việc: các trạng thái của quy trình làm việc áp dụng cho bảng này sẽ trở thành các làn. Khi kéo thẻ, màn hình xác nhận thao tác quy trình làm việc dẫn đến trạng thái đó sẽ mở ra, nên việc di chuyển không được quy trình làm việc cho phép sẽ bị từ chối.',
            'kanban_wip_enforce' => 'Quyết định điều gì xảy ra khi thả thẻ vào cột đã đạt giới hạn WIP.<br/>"Cho phép" giữ cách hoạt động cũ: tiêu đề chuyển màu đỏ và thẻ vẫn được di chuyển.<br/>"Hỏi xác nhận trước" hiển thị thông báo xác nhận và chỉ di chuyển thẻ khi bạn đồng ý.<br/>"Không cho phép" làm mờ cột đã đầy trong khi kéo và từ chối việc thả.<br/>*Các cột không đặt giới hạn WIP không bị ảnh hưởng.<br/>*Thẻ khớp với "Giá trị được coi là khẩn cấp" được miễn quy tắc này nhưng vẫn được đếm - nên tiêu đề vẫn hiển thị là cột đã vượt giới hạn.',
            'kanban_policies' => 'Quy tắc hiển thị trên tiêu đề cột - di chuột lên dấu hiệu để đọc nội dung.<br/>Ví dụ: ở cột "Đang kiểm thử" ghi "tất cả các mục trong bảng kiểm thử phải được duyệt trước khi chuyển tiếp", điều kiện để chuyển tiếp sẽ hiển thị cho cả nhóm.<br/>*Cột áp dụng được chọn từ các giá trị của bảng (hoặc trạng thái của quy trình làm việc).<br/>*Cài đặt không khớp với các cột đang hiển thị sẽ bị bỏ qua.',
            'kanban_wips' => 'Số thẻ tối đa mà một làn có thể chứa. Làn áp dụng được chọn từ các giá trị của bảng (hoặc trạng thái của quy trình làm việc), không cần nhập tay.<br/>*Làn vượt quá giới hạn sẽ có tiêu đề màu đỏ.<br/>*Cài đặt không khớp với các làn đang hiển thị sẽ bị bỏ qua.<br/>*Khi đếm số thẻ, giới hạn là 1 đến 999. Khi chỉ định "Cách đếm giới hạn WIP (cột số)", hãy nhập giới hạn của tổng cột đó (có thể lớn hơn 999).',
            'kanban_done_keys' => 'Các làn mang nghĩa "hoàn thành", chọn từ các giá trị của bảng.<br/>*Các bản ghi này sẽ dừng đếm ngược hạn chót và được tính là "Hoàn thành" trên thanh tổng hợp.<br/>*Với bảng Kanban tạo từ quy trình làm việc, mọi trạng thái được đặt là hoàn thành đã tự động được coi là hoàn thành, nên không cần cài đặt ở đây.<br/>*Cài đặt không khớp với các làn đang hiển thị sẽ bị bỏ qua.',
            'kanban_title_column' => 'Cột hiển thị làm tiêu đề in đậm trong thẻ.<br/>*Khi được đặt, tên hiển thị của bản ghi sẽ hiện dưới dạng liên kết ở đầu thẻ.<br/>*Khi không đặt, tên hiển thị của bản ghi sẽ trở thành tiêu đề.',
            'kanban_assignee_column' => 'Cột chứa người phụ trách.<br/>*Được hiển thị kèm ảnh đại diện ở cuối thẻ; thẻ chưa nhập sẽ hiển thị "Chưa phân công".<br/>*Cũng được dùng cho thanh tổng hợp, bộ lọc "Chỉ chưa phân công" và phân công hàng loạt.<br/>*<b>Nếu để trống</b>, bảng Kanban sẽ không có ảnh đại diện, ô "Chưa phân công", bộ lọc "Chỉ chưa phân công", phân công hàng loạt, thay đổi người phụ trách trên thẻ và tự động phân công. Nút "Của tôi" cũng không hiển thị, trừ khi đã đặt cột trong "Cột dùng để xác định "Của tôi"".',
            'kanban_mine_column' => 'Cột mà nút "Của tôi" trên thanh công cụ dùng để xác định thẻ nào là của bạn.<br/>*Nếu không đặt, cột người phụ trách sẽ được sử dụng. Chọn cột người yêu cầu để chỉ hiển thị các công việc do bạn đề nghị.<br/>*Có thể dùng cột người dùng và tổ chức, cũng như cột tham chiếu đến bảng có đúng một cột người dùng (các hàng liên kết với bạn sẽ được tìm qua cột đó).<br/>*Nếu cột không thể xác định ai đang xem (ví dụ cột lựa chọn thông thường), nút sẽ không hiển thị.',
            'kanban_filter_columns' => 'Chỉ chọn những cột cần hiển thị trong bảng lọc. Các cột được hiển thị theo thứ tự bạn chọn.<br/>*Nếu không đặt, mọi cột mà bảng Kanban đọc (cột có thể nhóm, người phụ trách, các trường trên thẻ...) đều được hiển thị, danh sách sẽ rất dài với bảng có nhiều cột.<br/>*Ô từ khóa, nhóm, làn bơi (swimlane) và các hộp kiểm luôn được hiển thị bất kể cài đặt này.',
            'kanban_limit_column' => 'Cột ngày hạn chót.<br/>*Dựa vào chênh lệch với thời điểm hiện tại, thẻ hiển thị huy hiệu "còn lại", "sắp đến hạn" hoặc "quá hạn".<br/>*Bản ghi có làn được coi là hoàn thành sẽ hiển thị "đạt" thay vào đó.<br/>*<b>Nếu để trống</b>, bảng Kanban sẽ không có huy hiệu hạn chót, ô "Quá hạn", bộ lọc "Chỉ quá hạn" và thay đổi hạn chót trên thẻ.',
            'kanban_sum_column' => 'Hiển thị tổng của cột số này dưới tiêu đề làn.<br/>Ví dụ: chọn cột số tiền, tiêu đề sẽ hiển thị "Giám đốc phê duyệt &yen;34,700,000", giúp thấy ngay số tiền đang bị tồn đọng ở một làn.<br/>*Chỉ để hiển thị - không ảnh hưởng đến giới hạn WIP.<br/>*Dấu phân cách chữ số và ký hiệu tiền tệ theo cài đặt của chính cột đó.<br/>*Khi lọc bảng Kanban, chỉ tính tổng các thẻ còn hiển thị trên màn hình.',
            'kanban_blocked_keys' => 'Chọn các giá trị biểu thị công việc đang bị dừng. Thẻ có các giá trị này sẽ có viền đỏ và biểu tượng cờ, đồng thời mục "Đang bị chặn" được thêm vào hàng KPI và bảng lọc.<br/>Ví dụ: "Tạm hoãn" và "Trả lại" của cột trạng thái, hoặc "Có" của một cột riêng cho trạng thái bị chặn.<br/>*Không nhất thiết phải là cột dùng để nhóm bảng - có thể chọn bất kỳ giá trị nào của bất kỳ cột nào.<br/>*Nhờ đó có thể phân biệt bằng mắt công việc đang tiến triển và công việc đang bị đình trệ.',
            'kanban_expedite_keys' => 'Chọn các giá trị biểu thị việc khẩn cấp cần chen ngang. Thẻ có các giá trị này sẽ có viền nổi bật, và khi bảng được chia làn theo chính cột đó thì làn này được cố định ở trên cùng.<br/>Ví dụ: "Khẩn cấp" của cột mức độ ưu tiên.<br/>*Thẻ khẩn cấp không bị giới hạn bởi "Di chuyển vào cột đã đầy", theo nguyên tắc Kanban thông thường là việc chen ngang được phép vượt giới hạn. Tuy nhiên chúng vẫn được tính vào số lượng, nên việc vượt giới hạn vẫn hiển thị trên màn hình.<br/>*Nếu đánh dấu quá nhiều giá trị là khẩn cấp thì dấu hiệu sẽ mất ý nghĩa - vui lòng chỉ chọn một hoặc hai giá trị.',
            'kanban_hide_keys' => 'Không hiển thị trên bảng các cột tương ứng với giá trị đã chọn.<br/>Ví dụ: bỏ "Hoàn thành" và "Đã hủy" thì bảng chỉ còn những công việc đang tiến hành.<br/>*Dữ liệu của các cột bị ẩn sẽ không được tải, nên với bảng có nhiều bản ghi, chỉ riêng việc này cũng giúp hiển thị nhanh hơn đáng kể.<br/>*Các cột này cũng không được tính vào tổng, trung bình và hàng KPI.<br/>*Với bảng theo quy trình làm việc, khi chuyển bản ghi sang trạng thái bị ẩn, thẻ sẽ biến mất khỏi bảng (bản thân dữ liệu vẫn được giữ nguyên).<br/>*Không thể ẩn cột "Chưa thiết lập".<br/>*Thiết lập không khớp với các cột Kanban đang hiển thị sẽ bị bỏ qua.',
            'kanban_col_count' => 'Số thẻ được tải ban đầu cho mỗi cột.<br/>0 (để trống) giữ cách hoạt động cũ: tải toàn bộ bảng trong một lần, tối đa bằng "Số bản ghi hiển thị tối đa".<br/>Nếu nhập 50, mỗi cột sẽ tải 50 thẻ và hiển thị nút "Xem thêm" bên dưới.<br/>*Khi đó số lượng, tổng, số ngày tồn đọng trung bình và hàng KPI được tính trên toàn bộ dữ liệu, không chỉ trên các thẻ đã tải.<br/>*Nên dùng cách này khi bảng có hàng nghìn bản ghi - bảng sẽ không còn bị giới hạn bởi "Số bản ghi hiển thị tối đa".<br/>*Khi chia làn theo làn bơi đã thiết lập trong chế độ xem, số lượng của từng ô (cột x làn) cũng được tính trên toàn bộ dữ liệu.<br/>*Khi lọc, tìm kiếm theo từ khóa, đổi cách nhóm, hoặc chọn một cột khác làm làn bơi trên màn hình, số liệu sẽ chỉ được tính trên các thẻ đã tải.',
            'kanban_col_age' => 'Hiển thị dưới tiêu đề cột số ngày trung bình mà các thẻ trong cột đó đã nằm tại đó.<br/>*Giúp nhận biết công đoạn nào đang bị tồn đọng (điểm nghẽn).<br/>*Với quy trình làm việc, số ngày được tính từ thời điểm bản ghi chuyển sang trạng thái đó; các trường hợp khác tính từ lần cập nhật cuối.',
            'kanban_progress_column' => 'Cột số được hiển thị dưới dạng thanh tiến độ bên dưới tiêu đề thẻ (ví dụ: tỷ lệ tiến độ).<br/>*0-49% màu xanh dương, 50-99% màu cam, 100% màu xanh lá.<br/>*Thẻ có giá trị trống sẽ không hiển thị thanh.',
            'kanban_progress_max' => 'Giá trị được tính là 100% của thanh tiến độ.<br/>Ví dụ: 100 với tỷ lệ phần trăm, 10 với quy trình gồm 10 bước.<br/>*Nếu để trống, giá trị là 100.',
            'kanban_history' => 'Hiển thị lịch sử quy trình làm việc (khi nào, ai, thao tác gì) trong bảng chi tiết của thẻ.<br/>*Chỉ tải cho thẻ đang mở, nên tốc độ hiển thị của bảng không bị ảnh hưởng.<br/>*Chỉ hiển thị ở các bảng có sử dụng quy trình làm việc.',
            'kanban_wip_column' => 'Tính giới hạn WIP bằng tổng của cột số này thay vì số lượng thẻ.<br/>Ví dụ: chọn cột số lượng thì tiêu đề cột sẽ hiển thị như "1550/1200".<br/>*Để trống thì vẫn tính theo số lượng thẻ như trước.<br/>*Chỉ có thể chọn cột số nguyên, số thập phân và tiền tệ.',
            'kanban_limit_warn' => 'Thẻ còn ít hơn số giờ này đến hạn sẽ chuyển sang màu vàng ("Sắp đến hạn").<br/>Ví dụ: 2 với yêu cầu hỗ trợ, 48 (=2 ngày) với ngày giao hàng.<br/>*Nếu để trống, giá trị là 2 giờ.',
            'kanban_age_steps' => 'Nhập ba số ngày theo thứ tự tăng dần, phân cách bằng dấu phẩy, để viền thẻ chuyển sang màu vàng, cam và đỏ.<br/>Ví dụ: 1,2,3 cho yêu cầu hỗ trợ, 3,7,14 cho quy trình dài.<br/>*Nếu không phải ba số tăng dần, hệ thống sẽ xem là 1,2,3.',
            'kanban_age_column' => 'Cột ngày dùng làm mốc tính số ngày đã trôi qua (ví dụ: ngày tiếp nhận).<br/>*Mép trái của thẻ đổi màu theo số ngày (1 ngày màu vàng, 2 ngày màu cam, từ 3 ngày trở lên màu đỏ).<br/>*Cũng được dùng cho mục "Số ngày trôi qua trung bình" trên thanh tổng hợp.',
            'kanban_ai_column' => 'Cột dùng để chọn người phụ trách được đề xuất (ví dụ: nhóm phụ trách).<br/>*Người xử lý giá trị đó nhiều nhất sẽ được đề xuất cho các thẻ chưa có người phụ trách.<br/>*Nút "Tự động phân công" chỉ hiển thị khi đã thiết lập cả cột này và "Cột người phụ trách".',
            'kanban_cover_column' => 'Cột hình ảnh được hiển thị làm ảnh bìa ở phía trên thẻ.<br/>*Bản ghi không có hình ảnh sẽ hiển thị không có ảnh bìa.<br/>*Nếu có nhiều hình ảnh, ảnh đầu tiên sẽ được sử dụng.<br/>*Hình ảnh được tải lên hoặc thay đổi trong cột này trên màn hình chỉnh sửa dữ liệu.',
            'kanban_cover_fit' => 'Cách hiển thị ảnh bìa trong khung.<br/>*"Lấp đầy" phủ kín khung và cắt bỏ phần thừa.<br/>*"Hiển thị toàn bộ" hiển thị trọn vẹn hình ảnh, có thêm khoảng trống hai bên.',
            'kanban_labels_column' => 'Cột lựa chọn được hiển thị dưới dạng nhãn màu ở phía trên thẻ.<br/>*Cũng có thể chọn cột cho phép chọn nhiều giá trị: mỗi giá trị sẽ có một nhãn riêng.<br/>*Cột này cũng được thêm vào bảng lọc, cho phép lọc các thẻ có bất kỳ nhãn nào trùng khớp.',
            'kanban_labels_style' => 'Kiểu hiển thị của nhãn.<br/>*"Chip" là nhãn nhỏ có chữ, "Thanh màu" là dải màu mỏng không có chữ (kiểu Trello).',
            'kanban_badge_column' => 'Cột được hiển thị dưới dạng huy hiệu nhỏ ở góc trên bên phải của thẻ (số lượng, điểm, số thứ tự...).<br/>*Bản ghi có giá trị trống sẽ không hiển thị huy hiệu.',
            'kanban_kpi' => 'Nếu chọn YES, thanh tổng hợp số lượng sẽ được hiển thị phía trên bảng Kanban.',
            'kanban_quickadd' => 'Nếu chọn YES, mỗi cột sẽ có ô nhập để tạo bản ghi chỉ bằng phím Enter.<br/>*Chỉ cột tên hiển thị và giá trị của cột đó được điền.',
            'kanban_bulk' => 'Nếu chọn YES, có thể nhấn Shift+click để chọn nhiều thẻ và thay đổi giá trị cùng lúc.',
            'kanban_editform' => 'Nếu chọn YES, khi nhấp vào thẻ, biểu mẫu chỉnh sửa của bản ghi đó sẽ mở ra phía trên bảng. Khi lưu, biểu mẫu sẽ đóng và chỉ thẻ đó được cập nhật lại.<br/>*Không hiển thị với người không có quyền chỉnh sửa.<br/>*Nếu chọn NO, thao tác nhấp sẽ theo thiết lập "Bảng chi tiết" bên dưới.',
            'kanban_drawer' => 'Nếu chọn YES, khi nhấp vào thẻ, bảng chi tiết sẽ mở ra ở bên phải.<br/>*Nếu chọn NO, hệ thống sẽ chuyển đến trang chi tiết của bản ghi.<br/>*Nếu "Mở biểu mẫu chỉnh sửa" ở trên cũng là YES, thao tác nhấp sẽ mở biểu mẫu chỉnh sửa, còn bảng chi tiết được mở từ nút "i" ở góc trên bên phải của thẻ.',
            'kanban_position' => 'Chọn vị trí hiển thị cột này trong thẻ.',
            'kanban_style' => 'Hiển thị cột này trên thẻ theo mẫu thiết lập sẵn đã chọn.<br/>*Được ưu tiên hơn thiết lập của cột.<br/>*Dùng nút bút chì để tạo mới hoặc chỉnh sửa mẫu thiết lập sẵn.<br/>*Nếu để trống, thẻ sẽ theo thiết lập của cột; nếu cột cũng không có thiết lập thì hiển thị dạng "tên và giá trị".',
            'kanban_icon' => 'Nhập tên class của Font Awesome, ví dụ fa-phone.<br/>Để mỗi lựa chọn có biểu tượng riêng, vui lòng nhập các cặp giá trị và tên class nối với nhau bằng dấu hai chấm, phân cách bằng dấu phẩy.<br/>Ví dụ: phone:fa-phone,mail:fa-envelope,chat:fa-comments',
