            'filter_ignored' => 'Điều kiện hiển thị chưa được thiết lập điều kiện đã bị bỏ qua. Vui lòng mở màn hình cài đặt chế độ xem và chọn lại điều kiện.',
            'kanban_no_group_column' => 'Chưa thiết lập cột dùng làm cột Kanban. Vui lòng mở cài đặt chế độ xem và chọn "Cột dùng làm cột Kanban".',
            'kanban_group_column_required' => 'Vui lòng chọn "Cột dùng làm cột Kanban". Với bảng Kanban tạo từ cột lựa chọn, không thể hiển thị bảng nếu thiếu mục này.',
            'kanban_age_steps_format' => 'Vui lòng nhập "Phân màu theo số ngày" theo dạng "1,2,3" (3 số phân cách bằng dấu phẩy, tăng dần).',
            'gantt_no_date_setting' => 'Để hiển thị biểu đồ Gantt, cần thiết lập cả "Cột ngày bắt đầu" và "Cột ngày đến hạn (ngày kết thúc)". Vui lòng chọn các cột ngày trên màn hình cài đặt chế độ xem.',
            'gantt_over_limit' => 'Số bản ghi vượt quá giới hạn (%s). Vui lòng thu hẹp bằng điều kiện hiển thị.',
