        'admin_help' => 'Đây là các khóa API do người dùng của trang này tạo. Có thể dừng ngay một khóa hoặc tất cả khóa của một người dùng. Khóa cũng không thể sử dụng khi người dùng hoặc thông tin đăng nhập bị xóa, hoặc khi người dùng bị loại khỏi nhóm vai trò trong quản lý tính năng. Khóa của người dùng SSO vẫn sử dụng được sau khi IdP dừng người dùng đó, cho đến khi hết hạn hoặc bị dừng tại đây: khi có người nghỉ việc, vui lòng dùng "Dừng tất cả khóa của người dùng này".',
