        'allowed_ips_help' => 'Mỗi dòng một địa chỉ (192.0.2.10, 198.51.100.0/24). Để trống: cho phép từ mọi nơi (giới hạn IP API của toàn trang vẫn được áp dụng). Khi đặt sau bộ cân bằng tải, địa chỉ thực chỉ được dùng nếu quản trị viên đã cài đặt ADMIN_TRUST_PROXY_IPS; nếu không, địa chỉ của bộ cân bằng tải sẽ được dùng. Khi đặt sau CloudFront, đó là địa chỉ của CloudFront.',
