        'description' => 'Quyết định tính năng và plugin nào được sử dụng, ai được sử dụng và có hiển thị menu hay không.',
        'help' => 'Tính năng mới ban đầu ở trạng thái tắt. Tính năng đang tắt không hiển thị trong menu, và không thể mở các trang của tính năng ngay cả bằng URL. Dữ liệu vẫn được giữ lại, nên khi bật lại, mọi thứ sẽ trở lại như cũ. Quản trị viên hệ thống luôn có thể sử dụng các tính năng đang bật.',
