        'confirm_stop' => 'Một số người dùng sẽ không thể sử dụng các mục sau nữa. Bạn có muốn lưu không?',
        'studio_note' => 'Danh sách và việc tạo màn hình: chỉ những người được chọn tại đây có quyền cài đặt bảng. Ứng dụng điện thoại: những người được chọn tại đây.',
        'features' => [
            'file_server' => 'Chia sẻ tệp',
            'file_server_help' => 'Không gian làm việc, thư mục, quản lý phiên bản và liên kết chia sẻ. Tắt tính năng này không làm xóa tệp. Sau khi bật, vui lòng tạo không gian làm việc trong màn hình Chia sẻ tệp và thêm thành viên (quản trị viên hệ thống tạo không gian làm việc).',
            'studio' => 'Studio',
            'studio_help' => 'Danh sách màn hình, tạo màn hình và ứng dụng điện thoại (/app).',
            'api_keys' => 'Khóa API của người dùng',
            'api_keys_help' => 'Nếu chọn "Tất cả người dùng", mọi người đều có thể tạo khóa của riêng mình. Người dùng thuộc nhóm vai trò đã chọn có thể tạo khóa API của riêng mình. Khóa chỉ có thể làm những việc người dùng được phép làm, trong phạm vi đã chọn cho khóa (chỉ đọc, một số bảng). Khóa có ngày hết hạn và có thể giới hạn theo địa chỉ IP hoặc chứng chỉ máy khách. Khi tắt tính năng này, không khóa nào hoạt động (các khóa vẫn được giữ lại).',
            'mcp' => 'MCP (kết nối từ AI)',
            'mcp_help' => 'AI như Claude có thể tìm kiếm và đọc dữ liệu của Exment (hiện tại chỉ đọc). AI đăng nhập giống như API (OAuth hoặc khóa API của người dùng) và chỉ xem được những gì người dùng đó được phép xem. Chỉ người dùng thuộc nhóm vai trò đã chọn. Những gì AI đã thực hiện được ghi vào nhật ký thao tác với tên "MCP".',
            'safety_check' => 'Xác nhận an toàn',
            'data_maintenance' => 'Bảo trì dữ liệu',
            'data_maintenance_help' => 'Quản trị viên của bảng sắp xếp dữ liệu của bảng cùng lúc (hiện tại: xóa hàng loạt tệp đính kèm). Tệp đã xóa không thể khôi phục. Người dùng có quyền thay đổi bảng có thể sử dụng.',
            'safety_check_help' => 'Hỏi xem người dùng có an toàn hay không, ví dụ sau khi xảy ra động đất (màn hình gửi, màn hình trả lời, gửi tự động theo thông tin động đất, trả lời qua LINE). Tắt tính năng này không làm xóa các bản ghi đã gửi và câu trả lời.',
            'tuning' => 'Tinh chỉnh hiệu năng',
            'tuning_help' => 'Kiểm tra các cài đặt giúp trang chạy nhanh hơn ("Tinh chỉnh hiệu năng" trong "Cài đặt: Hệ thống"). Chỉ dành cho quản trị viên hệ thống. Những gì cần thay đổi là cài đặt máy chủ, như php.ini và .env.',
            'maintenance_mode' => 'Chế độ bảo trì',
            'maintenance_mode_help' => 'Trong khi di chuyển dữ liệu hoặc cài đặt plugin, chỉ quản trị viên hệ thống có thể truy cập. Những người khác sẽ thấy màn hình "Đang bảo trì". Chỉ quản trị viên hệ thống có thể bật và tắt chế độ này.',
            'scheduled_jobs' => 'Tác vụ theo lịch',
            'scheduled_jobs_help' => 'Các tác vụ mà cron của máy chủ chạy (schedule:run): danh sách, các lần chạy gần đây và "Chạy ngay". Quản trị viên hệ thống được báo khi một tác vụ thất bại nhiều lần liên tiếp. Các lần chạy chỉ được lưu khi tính năng đang được dùng. Chỉ quản trị viên hệ thống dùng được.',
            'api_members' => 'API thành viên của tổ chức và nhóm vai trò',
            'api_members_help' => 'Đọc và thay đổi người dùng của tổ chức và người dùng, tổ chức của nhóm vai trò bằng API. Chỉ quản trị viên hệ thống và người có quyền quản lý nhóm vai trò. Nhóm vai trò có quyền hệ thống chỉ quản trị viên hệ thống mới thay đổi được.',
            'api_rate_raise' => 'Tạm thời nâng giới hạn API',
            'api_rate_raise_help' => 'Cho một người dùng hoặc API client gọi API nhiều lần hơn mỗi phút cho đến một thời điểm, khi nhập hoặc chuyển dữ liệu. Hết hạn thì quay về giới hạn cũ. Chỉ quản trị viên hệ thống dùng được.',
